import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String tStr = br.readLine();if (tStr != null) {int t = Integer.parseInt(tStr.trim());while (t-- > 0) {char[][] grid = new char[9][9];for (int i = 0; i < 9; i++) {String line = br.readLine();grid[i] = line.toCharArray();for (int j = 0; j < 9; j++) {if (grid[i][j] == '1') {grid[i][j] = '2';}}}for (int i = 0; i < 9; i++) {out.println(new String(grid[i]));}}}out.flush();out.close();}}